import random, sys, json, copy
sys.path.insert(0,'/workspace/tmp')
from tlib import run
from tplan import Brute
from test_plan import gen_case

def alt_witness(prof, fab, plan):
    """Build a certificate with different (still optimal) predecessor choices."""
    b=Brute(prof,fab); g=plan['guard_ns']
    P,N=b.P,b.N
    env=b.envelope(g)
    Lb={(p,i):env[(p,i)][0] for p in range(P) for i in range(N)}
    La={(p,i):env[(p,i)][1] for p in range(P) for i in range(N)}
    pred=[[None]*N for _ in range(P)]
    # BFS over tight edges from anchors, but visit nodes in reversed order to
    # pick different optimal predecessors
    from collections import deque
    reach={}
    q=deque()
    for p in range(P):
        for i in range(N):
            if b.anchored[p][i]:
                reach[(p,i)]=True; q.append((p,i))
    order=[]
    while q:
        cur=q.popleft(); order.append(cur)
        p,i=cur
        for (dn,dp,dt,cost) in b.steps(p,i,g):
            if Lb[(dp,dn)]==Lb[cur]+cost and La[(dp,dn)]==La[cur]+dt and (dp,dn) not in reach:
                reach[(dp,dn)]=True
                q.append((dp,dn))
    # assign preds: for each reachable non-anchor pick the LAST tight edge seen
    cand={}
    for p in range(P):
        for i in range(N):
            for (dn,dp,dt,cost) in b.steps(p,i,g):
                if (p,i) in reach and (dp,dn) in reach:
                    if Lb[(dp,dn)]==Lb[(p,i)]+cost and La[(dp,dn)]==La[(p,i)]+dt:
                        if b.anchored[dp][dn]: continue
                        # kind of this step
                        if (dn==(i) and dp==(p+1)%P and dt==1): kind=-1
                        else:
                            kind=None
                            for l,link in enumerate(b.links):
                                for d in (0,1):
                                    (n0,_,g0),(n1,_,g1),delays,defers=link
                                    src,dst=(n0,n1) if d==0 else (n1,n0)
                                    mm=(delays[d]+b.T-1)//b.T
                                    if src==i and dst==dn and mm+defers[d]==dt and (p+mm+defers[d])%P==dp:
                                        if cost==b.hop[ (g0 if d==0 else g1) ][ (g1 if d==0 else g0) ] + b.aging_cost(dst,p,delays[d],mm+defers[d]):
                                            kind=2*l+d
                        cand[(dp,dn)]=((p,i),kind)
    for p in range(P):
        for i in range(N):
            if b.anchored[p][i]:
                pred[p][i]=None
            elif (p,i) in cand:
                (u,kind)=cand[(p,i)]
                pred[p][i]=[u[0]*N+u[1],kind]
            else:
                pred[p][i]=plan['pred'][p][i]
    out=copy.deepcopy(plan)
    out['pred']=pred
    return out

# monkeypatch aging into Brute
def aging_cost(self,node,p,delay,dt):
    total=0; end=dt*self.T
    for j in range(dt):
        lo=j*self.T; hi=lo+self.T
        if lo<delay: lo=delay
        if hi>end: hi=end
        if hi>lo: total+=self.drift[(p+j)%self.P][node]*(hi-lo)
    return total
Brute.aging_cost=aging_cost

random.seed(23)
nacc=0; nrej=0
for seed in range(200, 400):
    case=gen_case(seed)
    if case is None: continue
    prof,fab=case
    [plan]=run([{"op":"plan","profile":prof,"fabric":fab}])
    if plan['status']!='ok': continue
    # 1. own plan accepted
    [res]=run([{"op":"audit","profile":prof,"fabric":fab,"proposal":plan}])
    assert res=={"valid":True}, (seed,'own plan rejected',res)
    nacc+=1
    # 2. alternative witness accepted
    if plan['guard_ns'] is not None:
        alt=alt_witness(prof,fab,plan)
        [res]=run([{"op":"audit","profile":prof,"fabric":fab,"proposal":alt}])
        assert res=={"valid":True}, (seed,'alt witness rejected',json.dumps(alt)[:2000])
        nacc+=1
    # 3. mutations must be rejected
    muts=[]
    def mut():
        return copy.deepcopy(plan)
    m=mut()
    if m['period_rounds'] is not None:
        m['period_rounds']+=1; muts.append(m); m=mut()
    for j in range(len(m['peaks_as'])):
        v=m['peaks_as'][j]
        m2=mut()
        m2['peaks_as'][j]= (v+3) if v is not None else 0
        muts.append(m2)
    if m['guard_ns'] is not None:
        m2=mut(); m2['guard_ns']+=1; muts.append(m2)
        m2=mut(); m2['guard_ns']=None
        m2['bounds_as']=None; m2['age_rounds']=None; m2['pred']=None; m2['warmup_cycle']=None
        muts.append(m2)
    if m['warmup_cycle'] is not None:
        m2=mut(); m2['warmup_cycle']+=1; muts.append(m2)
    if m['bounds_as'] is not None:
        P=len(m['bounds_as']); N=len(m['bounds_as'][0])
        for (pi,ni,field,delta) in [(0,0,'bounds_as',1),(P-1,N-1,'age_rounds',1),
                                    (0,0,'age_rounds',-1)]:
            m2=mut()
            if m2[field][pi][ni] is not None:
                m2[field][pi][ni]+=delta
                if isinstance(m2[field][pi][ni],int) and m2[field][pi][ni]>=0:
                    muts.append(m2)
        # corrupt pred
        m2=mut()
        done=False
        for p in range(P):
            for i in range(N):
                if m2['pred'][p][i] is not None:
                    m2['pred'][p][i]=[m2['pred'][p][i][0], m2['pred'][p][i][1]+1 if m2['pred'][p][i][1]!=-1 else 0]
                    done=True; break
            if done: break
        muts.append(m2)
        # drop a pred cell (make it unreachable-looking)
        m2=mut(); done=False
        for p in range(P):
            for i in range(N):
                if m2['pred'][p][i] is not None and not (p==0 and False):
                    m2['bounds_as'][p][i]=None; m2['age_rounds'][p][i]=None; m2['pred'][p][i]=None
                    done=True; break
            if done: break
        muts.append(m2)
        # out-of-range vertex
        m2=mut(); done=False
        for p in range(P):
            for i in range(N):
                if m2['pred'][p][i] is not None:
                    m2['pred'][p][i]=[P*N+7, m2['pred'][p][i][1]]
                    done=True; break
            if done: break
        muts.append(m2)
        # null bounds with finite age
        m2=mut(); done=False
        for p in range(P):
            for i in range(N):
                if m2['pred'][p][i] is not None:
                    m2['bounds_as'][p][i]=None
                    done=True; break
            if done: break
        muts.append(m2)
    # corrupt embedded calibration
    m2=mut(); m2['profile']['upper_ps'][0][0]=1; muts.append(m2)
    m2=mut()
    K=len(m2['profile']['upper_ps'])
    if K>1 and m2['profile']['pred'][0][1] is not None:
        m2['profile']['pred'][0][1]=(m2['profile']['pred'][0][1]+1)%(2*max(1,len(prof['measurements'])))
        muts.append(m2)
    m2=mut(); m2['profile']['status']='inconsistent'; m2['profile']['cycle']=[0]; muts.append(m2)
    for mm in muts:
        [res]=run([{"op":"audit","profile":prof,"fabric":fab,"proposal":mm}])
        assert res=={"valid":False}, (seed,'mutation accepted',json.dumps(mm)[:3000])
        nrej+=1
print('audit: accepted',nacc,'valid artifacts; rejected',nrej,'mutations')
